package com.mygo.music;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.media.*;
import android.media.session.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.lang.ref.WeakReference;
import java.util.*;

/** One player and queue survive Activity recreation, foreground/background changes and media controls. */
public class PlaybackService extends Service {
    public static final String ACTION_PLAY="com.mygo.music.PLAY",ACTION_QUEUE="com.mygo.music.QUEUE",ACTION_PAUSE="com.mygo.music.PAUSE",ACTION_RESUME="com.mygo.music.RESUME",ACTION_STOP="com.mygo.music.STOP",ACTION_NEXT="com.mygo.music.NEXT",ACTION_PREVIOUS="com.mygo.music.PREVIOUS";
    interface Listener {void changed(Snapshot snapshot);}
    static final class Snapshot {
        MediaPlayer player;boolean ready,loading,playing,remote,shuffle,repeat;String uri="",title="",error="",source="",stream="";long errorId,generation;int position,duration,volume,index;HashMap<String,String> headers=new HashMap<>();
    }
    public class Binder extends android.os.Binder {PlaybackService getService(){return PlaybackService.this;}}
    private final IBinder binder=new Binder();private final Handler main=new Handler(Looper.getMainLooper());private final ArrayList<WeakReference<Listener>> listeners=new ArrayList<>();
    private final Random random=new Random();private ArrayList<JSONObject> queue=new ArrayList<>();private int index=-1,percent=80,initialPosition;private long generation=System.nanoTime(),errorId=System.nanoTime();
    private boolean ready,loading,wanted,shuffle,repeat,foreground,resumeAfterFocus,ducked,closed,trackReported,currentCached;private String error="",quality="high",stream="";
    private MediaPlayer player;private HashMap<String,String> headers=new HashMap<>();private PluginManager plugins;private PluginRemote remote;private AudioCache cache;private SharedPreferences prefs;private AudioManager audio;private MediaSession session;private AudioFocusRequest focusRequest;private VolumeProvider remoteVolume;
    private final AudioManager.OnAudioFocusChangeListener focusListener=focus->{if(closed||remote.active())return;if(focus==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK){ducked=true;applyVolume();return;}if(focus==AudioManager.AUDIOFOCUS_GAIN){ducked=false;applyVolume();if(resumeAfterFocus){resumeAfterFocus=false;resume();}return;}if(focus<0){boolean resume=wanted;pauseInternal(false);resumeAfterFocus=focus==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT&&resume;}};
    private final BroadcastReceiver noisy=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(AudioManager.ACTION_AUDIO_BECOMING_NOISY.equals(intent.getAction()))pause();}};
    @Override public IBinder onBind(Intent intent){return binder;}
    @Override public void onCreate(){super.onCreate();prefs=getSharedPreferences("library",0);audio=(AudioManager)getSystemService(AUDIO_SERVICE);plugins=new PluginManager(getApplicationContext());cache=AudioCache.shared(this);shuffle=prefs.getBoolean("shuffle",false);repeat=prefs.getBoolean("repeat",false);remote=new PluginRemote(plugins,new PluginRemote.Listener(){public void state(JSONObject value){if(closed)return;String track=value.optString("trackId");for(int i=0;i<queue.size();i++){Uri uri=Uri.parse(queue.get(i).optString("uri"));if(remote.source().equals(uri.getAuthority())&&track.equals(uri.getQueryParameter("id"))){if(index!=i){index=i;generation++;trackReported=false;}break;}}ready=remote.ready();loading=false;wanted=remote.playing();percent=Math.max(0,Math.min(100,value.optInt("volume",percent)));if(remoteVolume!=null)remoteVolume.setCurrentVolume(percent);if(wanted)recordAndCache();publish();}public void error(String message){fail(message);}});
        session=new MediaSession(this,"MyGo Music");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){resume();}@Override public void onPause(){pause();}@Override public void onStop(){stopPlayback();}@Override public void onSkipToNext(){next();}@Override public void onSkipToPrevious(){previous();}@Override public void onSeekTo(long position){seek((int)Math.min(Integer.MAX_VALUE,position));}});session.setPlaybackToLocal(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());
        if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel("mygo-playback","MyGo Music 播放",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(channel);}
        IntentFilter filter=new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY);if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,filter);
        main.postDelayed(new Runnable(){public void run(){if(closed)return;if(index>=0&&(ready||loading)){persist();updateMediaState();}main.postDelayed(this,1000);}},1000);
    }
    @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();try{
        if(ACTION_QUEUE.equals(action)){ensureForeground();JSONArray values=new JSONArray(intent.getStringExtra("queue"));ArrayList<JSONObject> next=new ArrayList<>();for(int i=0;i<values.length();i++){JSONObject item=values.getJSONObject(i);String uri=item.optString("uri");if(uri.isEmpty())throw new IOException("歌曲缺少地址");next.add(item);}if(next.isEmpty())throw new IOException("播放队列为空");queue=next;shuffle=intent.getBooleanExtra("shuffle",false);repeat=intent.getBooleanExtra("repeat",false);percent=Math.max(0,Math.min(100,intent.getIntExtra("volume",80)));quality=intent.getStringExtra("quality");if(quality==null)quality="high";prefs.edit().putString("play_quality",quality).apply();resolve(intent.getIntExtra("index",0),intent.getIntExtra("position",0),true);
        }else if(ACTION_PLAY.equals(action)){ensureForeground();queue=new ArrayList<>();queue.add(new JSONObject().put("uri",intent.getStringExtra("uri")).put("title",intent.getStringExtra("title")));resolve(0,intent.getIntExtra("position",0),true);
        }else if(ACTION_PAUSE.equals(action))pause();else if(ACTION_RESUME.equals(action))resume();else if(ACTION_NEXT.equals(action))next();else if(ACTION_PREVIOUS.equals(action))previous();else if(ACTION_STOP.equals(action)||"STOP".equals(action))stopPlayback();
    }catch(Exception exception){fail(exception.getMessage()==null?"播放启动失败":exception.getMessage());}return START_NOT_STICKY;}
    static void startQueue(Context context,JSONArray queue,int index,int position,int volume,boolean shuffle,boolean repeat,String quality)throws IOException{String raw=queue.toString();if(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>500000)throw new IOException("播放队列过大，请减少队列中的歌曲");Intent intent=new Intent(context,PlaybackService.class).setAction(ACTION_QUEUE).putExtra("queue",raw).putExtra("index",index).putExtra("position",position).putExtra("volume",volume).putExtra("shuffle",shuffle).putExtra("repeat",repeat).putExtra("quality",quality);if(Build.VERSION.SDK_INT>=26)context.startForegroundService(intent);else context.startService(intent);}
    void addListener(Listener listener){for(WeakReference<Listener> reference:listeners)if(reference.get()==listener)return;listeners.add(new WeakReference<>(listener));listener.changed(snapshot());}
    void removeListener(Listener listener){listeners.removeIf(reference->reference.get()==null||reference.get()==listener);}
    MediaSession.Token token(){return session.getSessionToken();}
    Snapshot snapshot(){Snapshot value=new Snapshot();value.player=player;value.ready=ready;value.loading=loading;value.remote=remote.active();value.playing=remote.active()?remote.playing():ready&&player!=null&&safePlaying();value.position=position();value.duration=duration();value.index=index;value.volume=percent;value.shuffle=shuffle;value.repeat=repeat;value.error=error;value.errorId=errorId;value.generation=generation;value.stream=stream;value.headers=new HashMap<>(headers);if(index>=0&&index<queue.size()){value.uri=queue.get(index).optString("uri");value.title=queue.get(index).optString("title","歌曲");Uri uri=Uri.parse(value.uri);if("plugin".equals(uri.getScheme()))value.source=uri.getAuthority();}return value;}
    private boolean safePlaying(){try{return player.isPlaying();}catch(Exception ignored){return false;}}
    private int position(){try{return remote.active()?remote.position():ready&&player!=null?player.getCurrentPosition():Math.max(0,initialPosition);}catch(Exception ignored){return 0;}}
    private int duration(){try{return remote.active()?remote.duration():ready&&player!=null?player.getDuration():0;}catch(Exception ignored){return 0;}}
    private void resolve(int target,int position,boolean play){if(closed||target<0||target>=queue.size())return;long request=++generation;quality=prefs.getString("play_quality",quality);remote.clear(true);releasePlayer();index=target;initialPosition=Math.max(0,position);wanted=play;loading=true;ready=false;trackReported=false;currentCached=false;error="";resumeAfterFocus=false;stream="";headers.clear();session.setActive(true);session.setPlaybackToLocal(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());ensureForeground();publish();JSONObject item=queue.get(index);String original=item.optString("uri");Uri uri=Uri.parse(original);String name=item.optString("title","歌曲");File saved=cache.find(original,quality);if(saved!=null){prepare(request,Uri.fromFile(saved),new HashMap<>(),true);return;}
        if(!"plugin".equals(uri.getScheme())){prepare(request,uri,new HashMap<>(),false);return;}
        PluginManager.PluginInfo selected=null;for(PluginManager.PluginInfo info:plugins.list())if(info.enabled&&info.id.equals(uri.getAuthority())){selected=info;break;}if(selected==null){fail("插件未启用，且歌曲尚未完整缓存");return;}final PluginManager.PluginInfo source=selected;
        if("remote".equals(source.playback)){abandonFocus();JSONArray ids=new JSONArray();int start=0;for(int i=0;i<queue.size();i++){Uri song=Uri.parse(queue.get(i).optString("uri"));if("plugin".equals(song.getScheme())&&source.id.equals(song.getAuthority())){if(i==index)start=ids.length();ids.put(song.getQueryParameter("id"));}}remoteVolume=new VolumeProvider(VolumeProvider.VOLUME_CONTROL_ABSOLUTE,100,percent){@Override public void onSetVolumeTo(int value){setVolume(value);}@Override public void onAdjustVolume(int direction){setVolume(percent+direction*5);}};session.setPlaybackToRemote(remoteVolume);remote.play(source.id,ids,start,initialPosition,(ok,raw)->{if(closed||request!=generation)return;if(!ok){fail(raw);return;}loading=false;ready=true;if(!wanted)remote.pause();publish();});return;}
        try{plugins.export(source.id,"stream",new JSONObject().put("id",uri.getQueryParameter("id")).put("quality",quality),(ok,raw)->{if(closed||request!=generation)return;if(!ok){fail(raw);return;}try{JSONObject result=new JSONObject(raw);String address=result.optString("url");if(!address.startsWith("https://")&&!address.startsWith("http://"))throw new IOException("插件未返回音频地址");HashMap<String,String> values=new HashMap<>();JSONObject sourceHeaders=result.optJSONObject("headers");if(sourceHeaders!=null){Iterator<String> keys=sourceHeaders.keys();while(keys.hasNext()){String key=keys.next();values.put(key,sourceHeaders.getString(key));}}prepare(request,Uri.parse(address),values,false);}catch(Exception exception){fail(exception.getMessage());}});}catch(Exception exception){fail(exception.getMessage());}
    }
    private void prepare(long request,Uri address,HashMap<String,String> values,boolean cached){try{if(request!=generation||closed)return;stream=address.toString();currentCached=cached;headers=new HashMap<>(values);if(!headers.containsKey("User-Agent"))headers.put("User-Agent","MyGoMusic/5.6");cache.pin(cached?new File(address.getPath()):null);MediaPlayer created=new MediaPlayer();player=created;created.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());created.setWakeMode(getApplicationContext(),PowerManager.PARTIAL_WAKE_LOCK);if("http".equals(address.getScheme())||"https".equals(address.getScheme()))created.setDataSource(this,address,headers);else created.setDataSource(this,address);
        created.setOnPreparedListener(mp->{if(closed||request!=generation||player!=mp)return;ready=true;loading=false;applyVolume();if(initialPosition>0)mp.seekTo(Math.min(initialPosition,Math.max(0,mp.getDuration()-1)));if(wanted&&requestFocus())mp.start();else wanted=false;if(safePlaying())recordAndCache();publish();});
        created.setOnCompletionListener(mp->{if(request!=generation||closed)return;if(repeat)resolve(index,0,true);else next();});created.setOnErrorListener((mp,what,extra)->{if(request!=generation||closed)return true;if(cached&&index>=0&&index<queue.size())cache.remove(queue.get(index).optString("uri"),quality);fail(cached?"缓存音频无法播放，已清理，请重新播放":"音频播放失败："+what+" / "+extra);return true;});created.prepareAsync();publish();
    }catch(Exception exception){fail(exception.getMessage()==null?"音频无法准备":exception.getMessage());}}
    private void recordAndCache(){if(trackReported||index<0||index>=queue.size())return;trackReported=true;String original=queue.get(index).optString("uri"),title=queue.get(index).optString("title","歌曲");ArrayList<String> recent=new ArrayList<>();String old=prefs.getString("recent","");if(!old.isEmpty())recent.addAll(Arrays.asList(old.split("\n")));recent.remove(original);recent.add(0,original);while(recent.size()>30)recent.remove(recent.size()-1);prefs.edit().putString("recent",String.join("\n",recent)).apply();Uri uri=Uri.parse(original);if(currentCached||!"plugin".equals(uri.getScheme()))return;try{plugins.export(uri.getAuthority(),"played",new JSONObject().put("id",uri.getQueryParameter("id")),(ok,raw)->{});}catch(Exception ignored){}if(prefs.getBoolean("auto_cache",true)&&(stream.startsWith("https://")||stream.startsWith("http://")))cache.store(original,title,quality,stream,headers,(ok,message)->prefs.edit().putString("cache_status",message).apply());}
    void pause(){pauseInternal(true);}
    private void pauseInternal(boolean clearResume){if(clearResume)resumeAfterFocus=false;wanted=false;if(remote.active())remote.pause();else if(ready&&player!=null)try{player.pause();}catch(Exception ignored){}if(clearResume&&!remote.active())abandonFocus();publish();}
    void resume(){resumeAfterFocus=false;if(index<0||queue.isEmpty())return;wanted=true;ensureForeground();session.setActive(true);if(remote.active()){remote.resume();publish();}else if(ready&&player!=null){if(requestFocus()){player.start();recordAndCache();publish();}else{wanted=false;publish();}}else if(!loading)resolve(index,initialPosition,true);else publish();}
    void seek(int position){initialPosition=Math.max(0,position);if(remote.active())remote.seek(initialPosition);else if(ready&&player!=null)player.seekTo(Math.min(initialPosition,Math.max(0,player.getDuration()-1)));publish();}
    void setVolume(int value){percent=Math.max(0,Math.min(100,value));if(remote.active())remote.volume(percent);else applyVolume();publish();}
    void setModes(boolean shuffled,boolean repeated){shuffle=shuffled;repeat=repeated;prefs.edit().putBoolean("shuffle",shuffle).putBoolean("repeat",repeat).apply();publish();}
    void toggle(){if(loading){if(wanted)pause();else resume();}else if(snapshot().playing)pause();else resume();}
    void next(){if(queue.isEmpty())return;resolve(shuffle?random.nextInt(queue.size()):(index+1)%queue.size(),0,true);}
    void previous(){if(queue.isEmpty())return;resolve(index<=0?queue.size()-1:index-1,0,true);}
    void stopPlayback(){initialPosition=position();persist();++generation;wanted=false;loading=false;resumeAfterFocus=false;remote.clear(true);releasePlayer();cache.pin(null);abandonFocus();session.setActive(false);foreground=false;stopForeground(true);publish();stopSelf();}
    private boolean requestFocus(){if(Build.VERSION.SDK_INT>=26){if(focusRequest==null)focusRequest=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(focusListener,main).build();return audio.requestAudioFocus(focusRequest)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}return audio.requestAudioFocus(focusListener,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED;}
    private void abandonFocus(){if(Build.VERSION.SDK_INT>=26&&focusRequest!=null)audio.abandonAudioFocusRequest(focusRequest);else audio.abandonAudioFocus(focusListener);}
    private void applyVolume(){if(ready&&player!=null)player.setVolume(percent/100f*(ducked?0.2f:1f),percent/100f*(ducked?0.2f:1f));}
    private void releasePlayer(){ready=false;if(player!=null){player.setOnPreparedListener(null);player.setOnCompletionListener(null);player.setOnErrorListener(null);player.release();player=null;}}
    private void fail(String message){if(closed)return;error=message==null||message.isEmpty()?"播放失败":message;errorId++;wanted=false;loading=false;resumeAfterFocus=false;remote.clear(true);releasePlayer();cache.pin(null);abandonFocus();publish();}
    private void persist(){Snapshot value=snapshot();if(!value.uri.isEmpty())prefs.edit().putString("last_uri",value.uri).putInt("last_pos",value.position).apply();}
    private void publish(){if(closed)return;Snapshot value=snapshot();persist();updateMediaState();if(foreground)getSystemService(NotificationManager.class).notify(7,notification());for(Iterator<WeakReference<Listener>> iterator=listeners.iterator();iterator.hasNext();){Listener listener=iterator.next().get();if(listener==null)iterator.remove();else listener.changed(value);}}
    private void updateMediaState(){Snapshot value=snapshot();int state=!error.isEmpty()?PlaybackState.STATE_ERROR:loading?PlaybackState.STATE_BUFFERING:value.playing?PlaybackState.STATE_PLAYING:ready?PlaybackState.STATE_PAUSED:PlaybackState.STATE_STOPPED;PlaybackState.Builder playback=new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS|PlaybackState.ACTION_SEEK_TO|PlaybackState.ACTION_STOP).setState(state,value.position,value.playing?1f:0f,SystemClock.elapsedRealtime());if(!error.isEmpty())playback.setErrorMessage(error);session.setPlaybackState(playback.build());session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,value.title.isEmpty()?"MyGo Music":value.title).putString(MediaMetadata.METADATA_KEY_MEDIA_ID,value.uri).putLong(MediaMetadata.METADATA_KEY_DURATION,value.duration).build());}
    private PendingIntent action(String action,int request){return PendingIntent.getService(this,request,new Intent(this,PlaybackService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);}
    private Notification notification(){Snapshot value=snapshot();PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"mygo-playback"):new Notification.Builder(this);builder.setContentTitle(value.title.isEmpty()?"MyGo Music":value.title).setContentText(!error.isEmpty()?error:loading?"正在准备音频":value.playing?"正在播放":"已暂停").setSmallIcon(R.drawable.ic_launcher).setContentIntent(open).setColor(Color.rgb(147,88,190)).setVisibility(Notification.VISIBILITY_PUBLIC).setOngoing(value.playing||loading).setOnlyAlertOnce(true).setDeleteIntent(action(ACTION_STOP,14));builder.addAction(new Notification.Action.Builder(0,"上一首",action(ACTION_PREVIOUS,10)).build());builder.addAction(new Notification.Action.Builder(0,value.playing?"暂停":"继续",action(value.playing?ACTION_PAUSE:ACTION_RESUME,11)).build());builder.addAction(new Notification.Action.Builder(0,"下一首",action(ACTION_NEXT,12)).build());builder.addAction(new Notification.Action.Builder(0,"停止",action(ACTION_STOP,13)).build());builder.setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2));return builder.build();}
    private void ensureForeground(){if(!foreground){foreground=true;session.setActive(true);startForeground(7,notification());}}
    @Override public void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);try{unregisterReceiver(noisy);}catch(Exception ignored){}remote.close();releasePlayer();cache.pin(null);abandonFocus();plugins.close();session.release();listeners.clear();super.onDestroy();}
}
